import { Test } from 'ts-toolbelt'
import {
    Table,
    BooleanColumn,
    IntegerColumn,
    StringColumn,
    type Data,
    Record,
    type Schema,
    type FullSchema,
} from '../../db'

const ParentTableSchema = Table({
    name: 'parent',
    schema: {
        two: IntegerColumn({}),
        three: StringColumn({}),
        parentChoice: StringColumn({
            choices: {
                c: 'C',
                d: 'D',
            },
        }),
    },
})

const ChildTableSchema = Table({
    name: 'child',
    extends: 'parent',
    schema: {
        one: BooleanColumn({}),
        childChoice: StringColumn({
            choices: {
                a: 'A',
                b: 'B',
            },
        }),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface ParentTable extends Helper<typeof ParentTableSchema> {}
                interface ChildTable extends Helper<typeof ChildTableSchema> {}
            }

            interface Tables {
                parent: Table<TableSchemas.ParentTable>
                child: Table<TableSchemas.ChildTable, 'parent'>
            }
        }
    }
}

Test.checks([
    Test.check<keyof Schema<'child'>, 'one' | 'childChoice', Test.Pass>(),
    Test.check<keyof Data<'child'>, 'one' | 'childChoice' | 'two' | 'three' | 'parentChoice', Test.Pass>(),
    Test.check<keyof Schema<'parent'>, 'two' | 'three' | 'parentChoice', Test.Pass>(),
    Test.check<keyof Data<'parent'>, 'two' | 'three' | 'parentChoice', Test.Pass>(),
    Test.check<keyof FullSchema<'child'>, 'one' | 'two' | 'three' | 'parentChoice' | 'childChoice', Test.Pass>(),

    Test.check<keyof Schema<'child'>['childChoice']['choices'], 'a' | 'b', Test.Pass>(),
    Test.check<Schema<'child'>['childChoice']['choices']['a'], 'A', Test.Pass>(),
    Test.check<Schema<'child'>['childChoice']['choices']['b'], 'B', Test.Pass>(),
    Test.check<keyof Schema<'parent'>['parentChoice']['choices'], 'c' | 'd', Test.Pass>(),
    Test.check<Schema<'parent'>['parentChoice']['choices']['c'], 'C', Test.Pass>(),
    Test.check<Schema<'parent'>['parentChoice']['choices']['d'], 'D', Test.Pass>(),

    Test.check<Data<'child'>['one'], boolean | undefined, Test.Pass>(),
    Test.check<Data<'child'>['childChoice'], 'a' | 'b' | undefined, Test.Pass>(),
    Test.check<Data<'parent'>['two'], number | undefined, Test.Pass>(),
    Test.check<Data<'parent'>['three'], string | undefined, Test.Pass>(),
    Test.check<Data<'parent'>['parentChoice'], 'c' | 'd' | undefined, Test.Pass>(),
])

const ParentTableSchema2 = Table({
    name: 'parent2',
    schema: {
        one: StringColumn({ maxLength: 30 }),
    },
})

const ChildTableSchema2 = Table({
    name: 'child2',
    schema: {
        two: IntegerColumn({}),
    },
})

const GrandChildTableSchema = Table({
    name: 'grand_child',
    schema: {
        three: BooleanColumn({}),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface ParentTable2 extends Helper<typeof ParentTableSchema2> {}
                interface ChildTable2 extends Helper<typeof ChildTableSchema2> {}
                interface GrandChildTable extends Helper<typeof GrandChildTableSchema> {}
            }

            interface Tables {
                parent2: Table<TableSchemas.ParentTable2>
                child2: Table<TableSchemas.ChildTable2, 'parent2'>
                grand_child: Table<TableSchemas.GrandChildTable, 'child2'>
            }
        }
    }
}

Record({
    table: 'parent2',
    $id: 0,
    data: {
        one: 'parent',
    },
})

Record({
    table: 'child2',
    $id: 1,
    data: {
        one: 'child',
        two: 123,
    },
})

Record({
    table: 'child2',
    $id: 2,
    data: {
        // @ts-expect-error Number not assignable to string
        one: 999,
        two: 123,
    },
})

Record({
    table: 'grand_child',
    $id: 3,
    data: {
        one: 'grandchild',
        two: 123,
        three: true,
    },
})

Record({
    table: 'grand_child',
    $id: 4,
    data: {
        // @ts-expect-error Number not assignable to string
        one: 999,
        two: 123,
        three: true,
    },
})

Record({
    table: 'grand_child',
    $id: 5,
    data: {
        one: 'grandchild',
        // @ts-expect-error String not assignable to number
        two: '123',
        three: true,
    },
})
